import type { CHeader } from "../../shared/c-header";
import { valuesForEnumSpec } from "../../shared/enum-generation";
import { canonicalEnumSpecs } from "../../shared/model/enum-specs";
import type { AbiFunction, AbiModule, ArrayElement, ParamProjection, ReturnProjection, Scalar } from "./model";
import { csharpIdentifier } from "./names";

const HEADER = [
  "// <auto-generated>",
  "// Generated by v2/abi/generate-fui-cs.ts (fui-cs-ffi). Do not edit by hand.",
  "// </auto-generated>",
  "#nullable enable",
  "#pragma warning disable CS1591 // The projection mirrors the C headers, which document the ABI.",
];

const IMPORT_CLASS: Readonly<Record<AbiModule, string>> = {
  effindom_v2_ui: "UiImports",
  fui_fetch_host: "FetchHostImports",
  fui_host: "HostImports",
};

function scalarType(scalar: Scalar): string {
  switch (scalar) {
    case "bool": return "bool";
    case "f32": return "float";
    case "f64": return "double";
    case "i32": return "int";
    case "u32": return "uint";
    case "u64": return "ulong";
  }
}

/**
 * An input array crosses as a read-only span: NetWasm gives JavaScript a view of its memory for the call instead of a
 * copy, and the JavaScript module lowers it into the harness arena before the call returns.
 */
function arrayType(element: ArrayElement): string {
  switch (element) {
    case "f32": return "ReadOnlySpan<float>";
    case "u32": return "ReadOnlySpan<uint>";
    case "u8": return "ReadOnlySpan<byte>";
  }
}

function paramType(param: ParamProjection): string {
  switch (param.kind) {
    case "scalar": return param.enumName ?? scalarType(param.scalar);
    case "text": return "string";
    case "bytes": return "ReadOnlySpan<byte>";
    case "array": return arrayType(param.element);
    case "out": return `out ${scalarType(param.element)}`;
  }
}

function isSpanParam(param: ParamProjection): boolean {
  return param.kind === "bytes" || param.kind === "array";
}

function returnType(returns: ReturnProjection): string {
  return returns.scalar === "void" ? "void" : returns.enumName ?? scalarType(returns.scalar);
}

function hasOutputs(fn: AbiFunction): boolean {
  return fn.params.some((param) => param.kind === "out");
}

function signature(fn: AbiFunction): string {
  const params = fn.params.map((param) => `${paramType(param)} ${csharpIdentifier(param.name)}`).join(", ");
  return `${returnType(fn.returns)} ${fn.methodName}(${params})`;
}

function importSignature(fn: AbiFunction): string {
  const params = fn.params.flatMap((param) => {
    if (param.kind === "out") return [];
    const type = param.kind === "scalar" ? scalarType(param.scalar) : paramType(param);
    return [`${type} ${csharpIdentifier(param.name)}`];
  });
  const result = hasOutputs(fn) ? "double[]" : fn.returns.scalar === "void" ? "void" : scalarType(fn.returns.scalar);
  return `${result} ${fn.methodName}(${params.join(", ")})`;
}

function fromDouble(expression: string, scalar: Scalar, enumName?: string): string {
  if (scalar === "bool") return `${expression} != 0`;
  const value = `(${scalarType(scalar)})${expression}`;
  return enumName === undefined ? value : `(${enumName})${value}`;
}

/** Bit-set enums: C# gets [Flags] and a None member, since the ABI passes combinations of them. */
const FLAGS_ENUMS: ReadonlySet<string> = new Set(["KeyModifier", "HostCapability"]);

export function emitAbiInterfaceFile(functions: readonly AbiFunction[], uiSource: CHeader, coreSource: CHeader): string {
  const enums = canonicalEnumSpecs.map((spec) => {
    const values = valuesForEnumSpec(spec, uiSource, coreSource);
    const backing = spec.name === "HandleValue" ? "ulong" : "uint";
    const members = spec.members.map((member) => {
      const value = values.get(member.source);
      if (value === undefined) throw new Error(`Could not find ABI enum member ${member.source} for ${spec.name}.${member.name}.`);
      return `    ${member.name} = ${value},`;
    });
    if (!FLAGS_ENUMS.has(spec.name)) {
      return [`public enum ${spec.name} : ${backing}`, "{", ...members, "}"].join("\n");
    }
    if ([...values.values()].some((value) => Number(value) === 0)) {
      throw new Error(`Flags enum ${spec.name} already has a zero member; drop the generated None.`);
    }
    return ["[System.Flags]", `public enum ${spec.name} : ${backing}`, "{", "    None = 0,", ...members, "}"].join("\n");
  });
  const members = functions.map((fn) => `    ${signature(fn)};`);
  return [
    ...HEADER,
    "",
    "namespace FuiCs;",
    "",
    ...enums.flatMap((block) => [block, ""]),
    "/// <summary>The EffinDOM ABI calls fui-cs makes, at value level. Generated from the ABI functions fui-cs code calls.</summary>",
    "public partial interface IFuiAbi",
    "{",
    ...members,
    "}",
    "",
  ].join("\n");
}

function implementation(fn: AbiFunction): string[] {
  const args = fn.params.flatMap((param) => {
    if (param.kind === "out") return [];
    const name = csharpIdentifier(param.name);
    return [param.kind === "scalar" && param.enumName !== undefined ? `(${scalarType(param.scalar)})${name}` : name];
  });
  const call = `${IMPORT_CLASS[fn.module]}.${fn.methodName}(${args.join(", ")})`;
  if (!hasOutputs(fn)) {
    const value = fn.returns.enumName === undefined ? call : `(${fn.returns.enumName})${call}`;
    return [`    public ${signature(fn)} => ${value};`];
  }
  const lines = [`    public ${signature(fn)}`, "    {", `        double[] values = ${call};`];
  let index = 1;
  for (const param of fn.params) {
    if (param.kind !== "out") continue;
    lines.push(`        ${csharpIdentifier(param.name)} = ${fromDouble(`values[${String(index)}]`, param.element)};`);
    index += 1;
  }
  if (fn.returns.scalar !== "void") lines.push(`        return ${fromDouble("values[0]", fn.returns.scalar, fn.returns.enumName)};`);
  lines.push("    }");
  return lines;
}

export function emitJsImportFile(functions: readonly AbiFunction[]): string {
  const modules: AbiModule[] = ["effindom_v2_ui", "fui_host", "fui_fetch_host"];
  const importClasses = modules.flatMap((module) => {
    const members = functions.filter((fn) => fn.module === module).flatMap((fn) => [
      `    [JSImport("${fn.abiName}", "${module}")]`,
      `    internal static extern ${importSignature(fn)};`,
      "",
    ]);
    if (members.length === 0) return [];
    return [`internal static partial class ${IMPORT_CLASS[module]}`, "{", ...members.slice(0, -1), "}", ""];
  });
  return [
    ...HEADER,
    "",
    "using System;",
    "using System.Runtime.InteropServices.JavaScript;",
    "",
    "namespace FuiCs.Hosting;",
    "",
    "/// <summary>The browser implementation of <see cref=\"IFuiAbi\"/>: JSImport calls into the fui-cs JavaScript ABI modules. Compiled into each application.</summary>",
    "internal sealed partial class JsImportFuiAbi : IFuiAbi",
    "{",
    ...functions.flatMap((fn) => implementation(fn)),
    "}",
    "",
    ...importClasses,
  ].join("\n").replace(/\n+$/, "\n");
}

function recordingMember(fn: AbiFunction): string[] {
  // A span cannot be boxed into the recorded arguments; its contents are copied into an array.
  const args = fn.params.filter((param) => param.kind !== "out")
    .map((param) => (isSpanParam(param) ? `${csharpIdentifier(param.name)}.ToArray()` : csharpIdentifier(param.name)));
  const lines = [`    public virtual ${signature(fn)}`, "    {", `        Calls.Add(new AbiCall("${fn.abiName}", [${args.join(", ")}]));`];
  for (const param of fn.params) {
    if (param.kind === "out") lines.push(`        ${csharpIdentifier(param.name)} = default;`);
  }
  if (fn.returns.scalar === "u64" && fn.abiName.includes("create")) {
    lines.push("        return NextHandle++;");
  } else if (fn.returns.scalar !== "void") {
    lines.push("        return default;");
  }
  lines.push("    }");
  return lines;
}

export function emitRecordingFile(functions: readonly AbiFunction[]): string {
  return [
    ...HEADER,
    "",
    "using System.Collections.Generic;",
    "",
    "namespace FuiCs.Testing;",
    "",
    "/// <summary>One recorded ABI call: the ABI function name and its value-level arguments.</summary>",
    "public sealed record AbiCall(string Name, object?[] Arguments);",
    "",
    "/// <summary>",
    "/// Records every ABI call instead of reaching EffinDOM, for tests on desktop .NET and NetWasm.",
    "/// Creation calls return increasing handles; override a member to return other values.",
    "/// </summary>",
    "public partial class RecordingFuiAbi : IFuiAbi",
    "{",
    "    public List<AbiCall> Calls { get; } = [];",
    "",
    "    public ulong NextHandle { get; set; } = 1;",
    "",
    ...functions.flatMap((fn, index) => [...(index === 0 ? [] : [""]), ...recordingMember(fn)]),
    "}",
    "",
  ].join("\n");
}

/**
 * Hand-written JSImport modules, keyed by module name, with the C# ABI members that use them. A module is
 * registered when the C# source calls one of its members.
 */
export const HAND_WRITTEN_MODULES: ReadonlyMap<string, readonly string[]> = new Map([
  ["fui_host_buffers", [
    "HostTryCopyPersistedState",
    "UiReadTextRangeRects",
    "UiReadCrossSelectionEndpointRects",
    "HostGetOffscreenCanvasToken",
    "HostReadOffscreenPixels",
    "UiRenderNodeToRgba",
  ]],
]);

export function emitJsModulesProps(functions: readonly AbiFunction[], usedMethods: ReadonlySet<string>): string {
  const generated: string[] = ["effindom_v2_ui", "fui_host", "fui_fetch_host"];
  const handWritten = [...HAND_WRITTEN_MODULES]
    .filter(([, members]) => members.some((member) => usedMethods.has(member)))
    .map(([module]) => module);
  const items = [...generated.filter((module) => functions.some((fn) => fn.module === module)), ...handWritten]
    .map((module) => `    <NetWasmJavaScriptModule Include="$(FuiCsJavaScriptModulesDirectory)${module}.mjs" Module="${module}" />`);
  return [
    "<!-- Generated by v2/abi/generate-fui-cs.ts (fui-cs-ffi). Do not edit by hand. -->",
    "<!-- An app that never calls a module's imports (no fetch, say) trims them all, and NetWasm leaves the module out. -->",
    "<!-- FuiCs.Exports.targets sets the modules' directory: the package's js/ folder, or the repository's build/imports/. -->",
    "<Project>",
    "  <ItemGroup>",
    ...items,
    "  </ItemGroup>",
    "</Project>",
    "",
  ].join("\n");
}
